13	function generateHandles() {
14	  behaviorShim.specify("DIV.dd-handle", "hetero-list", -100, function (e) {
15	    e.addEventListener("mouseover", function () {
16	      this.closest(".repeated-chunk").classList.add("hover");
17	    });
18	    e.addEventListener("mouseout", function () {
19	      this.closest(".repeated-chunk").classList.remove("hover");
20	    });
21	  });
22	}
