24	function convertInputsToButtons(e) {
25	  let oldInputs = e.querySelectorAll("INPUT.hetero-list-add");
26	  oldInputs.forEach((oldbtn) => {
27	    let btn = document.createElement("button");
28	    btn.setAttribute("type", "button");
29	    btn.classList.add("hetero-list-add", "jenkins-button");
30	    btn.innerText = oldbtn.getAttribute("value");
31	    if (oldbtn.hasAttribute("suffix")) {
32	      btn.setAttribute("suffix", oldbtn.getAttribute("suffix"));
33	    }
34	    let chevron = createElementFromHtml(Symbols.CHEVRON_DOWN);
35	    btn.appendChild(chevron);
36	    oldbtn.parentNode.appendChild(btn);
37	    oldbtn.remove();
38	  });
39	}
