41	function generateButtons() {
42	  behaviorShim.specify(
43	    "DIV.hetero-list-container",
44	    "hetero-list-new",
45	    -100,
46	    function (e) {
47	      if (isInsideRemovable(e)) {
48	        return;
49	      }
50	
51	      convertInputsToButtons(e);
52	      let btn = Array.from(e.querySelectorAll("BUTTON.hetero-list-add")).pop();
53	
54	      let prototypes = e.lastElementChild;
55	      while (!prototypes.classList.contains("prototypes")) {
56	        prototypes = prototypes.previousElementSibling;
57	      }
58	      let insertionPoint = prototypes.previousElementSibling; // this is where the new item is inserted.
59	
60	      let templates = [];
61	      let children = prototypes.children;
62	      for (let i = 0; i < children.length; i++) {
63	        let n = children[i];
64	        let name = n.getAttribute("name");
65	        let descriptorId = n.getAttribute("descriptorId");
66	        let title = n.getAttribute("title");
67	
68	        templates.push({
69	          html: n.innerHTML,
70	          name: name,
71	          descriptorId: descriptorId,
72	          title: title,
73	        });
74	      }
75	      prototypes.remove();
76	      let withDragDrop = registerSortableDragDrop(e);
77	
78	      function insert(instance, template) {
79	        let nc = document.createElement("div");
80	        nc.className = "repeated-chunk";
81	        nc.setAttribute("name", template.name);
82	        nc.setAttribute("descriptorId", template.descriptorId);
83	        nc.innerHTML = template.html;
84	        nc.style.opacity = "0";
85	
86	        instance.hide();
87	
88	        renderOnDemand(
89	          nc.querySelector("div.config-page"),
90	          function () {
91	            function findInsertionPoint() {
92	              // given the element to be inserted 'prospect',
93	              // and the array of existing items 'current',
94	              // and preferred ordering function, return the position in the array
95	              // the prospect should be inserted.
96	              // (for example 0 if it should be the first item)
97	              function findBestPosition(prospect, current, order) {
98	                function desirability(pos) {
99	                  let count = 0;
100	                  for (let i = 0; i < current.length; i++) {
101	                    if (i < pos == order(current[i]) <= order(prospect)) {
102	                      count++;
103	                    }
104	                  }
105	                  return count;
106	                }
107	
108	                let bestScore = -1;
109	                let bestPos = 0;
110	                for (let i = 0; i <= current.length; i++) {
111	                  let d = desirability(i);
112	                  if (bestScore <= d) {
113	                    // prefer to insert them toward the end
114	                    bestScore = d;
115	                    bestPos = i;
116	                  }
117	                }
118	                return bestPos;
119	              }
120	
121	              let current = Array.from(e.children).filter(function (e) {
122	                return e.matches("DIV.repeated-chunk");
123	              });
124	
125	              function o(did) {
126	                if (did instanceof Element) {
127	                  did = did.getAttribute("descriptorId");
128	                }
129	                for (let i = 0; i < templates.length; i++) {
130	                  if (templates[i].descriptorId == did) {
131	                    return i;
132	                  }
133	                }
134	                return 0; // can't happen
135	              }
136	
137	              let bestPos = findBestPosition(template.descriptorId, current, o);
138	              if (bestPos < current.length) {
139	                return current[bestPos];
140	              } else {
141	                return insertionPoint;
142	              }
143	            }
144	            let referenceNode = e.classList.contains("honor-order")
145	              ? findInsertionPoint()
146	              : insertionPoint;
147	            referenceNode.parentNode.insertBefore(nc, referenceNode);
148	
149	            // Initialize drag & drop for this component
150	            if (withDragDrop) {
151	              registerSortableDragDrop(nc);
152	            }
153	
154	            new YAHOO.util.Anim(
155	              nc,
156	              {
157	                opacity: { to: 1 },
158	              },
159	              0.2,
160	              YAHOO.util.Easing.easeIn,
161	            ).animate();
162	
163	            Behaviour.applySubtree(nc, true);
164	            ensureVisible(nc);
165	            layoutUpdateCallback.call();
166	          },
167	          true,
168	        );
169	      }
170	
171	      function has(id) {
172	        return (
173	          e.querySelector('DIV.repeated-chunk[descriptorId="' + id + '"]') !=
174	          null
175	        );
176	      }
177	
178	      let oneEach = e.classList.contains("one-each");
179	
180	      generateDropDown(btn, (instance) => {
181	        let menuItems = [];
182	        for (let i = 0; i < templates.length; i++) {
183	          let n = templates[i];
184	          let disabled = oneEach && has(n.descriptorId);
185	          let type = disabled ? "DISABLED" : "button";
186	          let item = {
187	            label: n.title,
188	            onClick: (event) => {
189	              event.preventDefault();
190	              event.stopPropagation();
191	              insert(instance, n);
192	            },
193	            type: type,
194	          };
195	          menuItems.push(item);
196	        }
197	        const menuContainer = document.createElement("div");
198	        const menu = Utils.generateDropdownItems(menuItems, true);
199	        menuContainer.appendChild(createFilter(menu));
200	        menuContainer.appendChild(menu);
201	        instance.setContent(menuContainer);
202	      });
203	    },
204	  );
205	}
206	
207	function createFilter(menu) {
208	  const filterInput = createElementFromHtml(`
209	    <input class="jenkins-dropdown__filter-input" placeholder="Filter" spellcheck="false" type="search"/>
210	  `);
211	
212	  filterInput.addEventListener("input", (event) =>
213	    applyFilterKeyword(menu, event.currentTarget),
214	  );
215	  filterInput.addEventListener("click", (event) => event.stopPropagation());
216	  filterInput.addEventListener("keydown", (event) => {
217	    if (event.key === "Enter") {
218	      event.preventDefault();
219	    }
220	  });
221	
222	  const filterContainer = createElementFromHtml(`
223	    <div class="jenkins-dropdown__filter">
224	      <div class="jenkins-dropdown__item__icon">
225	        ${Symbols.FUNNEL}
226	      </div>
227	    </div>
228	  `);
229	  filterContainer.appendChild(filterInput);
230	  return filterContainer;
231	}
232	
233	function applyFilterKeyword(menu, filterInput) {
234	  const filterKeyword = (filterInput.value || "").toLowerCase();
235	  let items = menu.querySelectorAll(
236	    ".jenkins-dropdown__item, .jenkins-dropdown__disabled",
237	  );
238	  for (let item of items) {
239	    let match = item.innerText.toLowerCase().includes(filterKeyword);
240	    item.style.display = match ? "inline-flex" : "none";
241	  }
242	}
243	
244	function generateDropDown(button, callback) {
245	  tippy(
246	    button,
247	    Object.assign({}, Templates.dropdown(), {
248	      appendTo: undefined,
249	      onCreate(instance) {
250	        if (instance.loaded) {
251	          return;
252	        }
253	        instance.popper.addEventListener("click", () => {
254	          instance.hide();
255	        });
256	        instance.popper.addEventListener("keydown", () => {
257	          if (event.key === "Escape") {
258	            instance.hide();
259	          }
260	        });
261	      },
262	      onShow(instance) {
263	        callback(instance);
264	        button.dataset.expanded = "true";
265	      },
266	      onHide() {
267	        button.dataset.expanded = "false";
268	      },
269	    }),
270	  );
271	}
272	
273	export default { init };

